// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  const inputData = $input.first().json.output;

  // Проверяем наличие формата tavily(query="...")
  item.json.hasTavilyFormat = /tavily\s*\(\s*query\s*=\s*["'][^"']+["']\s*\)/i.test(inputData);
}

return $input.all();

const outputData = $input.first().json.output
// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  // Добавляем результат парсинга как новое поле
  item.json.parsedOutput = outputData;

  // Или парсим в зависимости от формата outputData
  if (typeof outputData === 'string') {
    try {
      // Пытаемся парсить JSON строку
      item.json.parsedJson = JSON.parse(outputData);
    } catch (e) {
      // Если не JSON, сохраняем как строку
      item.json.parsedJson = null;
      item.json.outputString = outputData;
    }
  } else if (typeof outputData === 'object' && outputData !== null) {
    // Если уже объект, используем как есть
    item.json.parsedJson = outputData;
  }

  // Добавляем поле с типом данных
  item.json.outputType = typeof outputData;
}

return $input.all();

// Извлекаем запрос из строки формата tavily(query="...")
const inputString = $input.first().json.output;

function extractQuery(input) {
    // Удаляем пробелы в начале и конце
    const trimmed = input.trim();

    // Вариант 1: Полный формат tavily(query="...")
    const tavilyRegex = /tavily\(query\s*=\s*"([^"]+)"\)/i;
    let match = trimmed.match(tavilyRegex);

    if (match && match[1]) {
        return match[1].trim();
    }

    // Вариант 2: Без tavily, но с query="..."
    const queryRegex = /query\s*=\s*"([^"]+)"/i;
    match = trimmed.match(queryRegex);

    if (match && match[1]) {
        return match[1].trim();
    }
return trimmed;
}
const extractedQuery = extractQuery(inputString);

// Возвращаем ПРОСТУЮ СТРОКУ с запросом (без слова query и скобок)
return [{ 
     json: {
       output: extractedQuery
     }
 }];

const tavilyData = $input.first().json;

// System message - задаем роль
const systemMessage = `Ты ИИ-агент внутри n8n, помощник по анализу поисковых результатов. Проанализируй предоставленные результаты поиска по запросу и составь структурированный ответ для пользователя.
Формат ответа:
- Естественный текст с абзацами
- Можно использовать маркированные списки для перечислений
- Без технических деталей, которые не были в источниках`;

// User message - передаем данные и задачу
const userMessage = `
ЗАПРОС ПОЛЬЗОВАТЕЛЯ: "${tavilyData.query}"

РЕЗУЛЬТАТЫ ПОИСКА (${tavilyData.results.length} источников, отсортированы по релевантности):
${tavilyData.results.map((result, index) => `
=== ИСТОЧНИК ${index + 1} ===
ОЦЕНКА РЕЛЕВАНТНОСТИ TAVILY (не вероятность достоверности): ${result.score}
ЗАГОЛОВОК: ${result.title}
URL: ${result.url}
СОДЕРЖАНИЕ: ${result.content}
`).join('\n')}

ИНСТРУКЦИЯ:
1. Проанализируй каждый результат (всего ${tavilyData.results.length} источников)
2. Извлеки ключевую информацию из поля 'content' каждого результата
3. Создай подробный, но понятный ответ на русском языке
4. Структурируй информацию логически
5. Учитывай релевантность (score) каждого источника
6. Используй информацию только из предоставленных данных

Начни анализ и дай полный ответ.
`;

return [{
  json: {
    system_message: systemMessage,
    user_message: userMessage,
    query: tavilyData.query,
    results_count: tavilyData.results.length
  }
}];
